from pathlib import Path
from datetime import datetime, timezone, timedelta
from concurrent.futures import ThreadPoolExecutor, as_completed
import hashlib, json, requests
root = Path.cwd()
out = root / "reports/research/510300_original_real_industrial_sales_and_base_joint_cause_source_review_v1"
def now():
    return datetime.now(timezone(timedelta(hours=8))).isoformat()
def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()
def save(name, value):
    path = out / name
    if path.exists():
        raise RuntimeError("首次来源产物已有，禁止重复：" + str(path))
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return {"path": str(path.relative_to(root)).replace("\\", "/"), "sha256": sha(path)}
protocol = json.loads((out / "protocol.json").read_text(encoding="utf-8"))
if sha(out / "protocol.json") != "9fe0d686e142e6e56ee04295e7c4feb4f7d7f0e090d164aad637a40a556d69a7":
    raise RuntimeError("来源口径变化")
selected_urls = {
    "2021M02": "https://www.stats.gov.cn/xxgk/sjfb/zxfb2020/202103/t20210315_1814762.html",
    "2021M08": "https://www.stats.gov.cn/xxgk/sjfb/zxfb2020/202109/t20210915_1822092.html"
}
selections = []
for query in protocol["queries_fixed_before_new_requests"]:
    period = query["economic_period"]
    result_file = out / ("固定定位原返回_" + period + "_E113.json")
    if not result_file.exists():
        raise RuntimeError("固定定位尚未执行：" + period)
    returned = json.loads(result_file.read_text(encoding="utf-8"))
    if returned["query"] != query:
        raise RuntimeError("实际定位与冻结文本不符")
    source = selected_urls.get(period)
    if source and source not in json.dumps(returned, ensure_ascii=False):
        raise RuntimeError("原候选不在对应原期的实际查询返回中")
    selections.append({"economic_period": period, "query": query, "query_return_path": str(result_file.relative_to(root)).replace("\\", "/"), "query_return_sha256": sha(result_file), "selected_url": source, "status": "SELECTED_FIRST_RETURNED_SAME_ORIGINAL_NATIONAL_INDUSTRIAL_QUANTITY" if source else "UNKNOWN_FIXED_LOCATOR_NO_MATCHING_ORIGINAL_PERIOD", "no_selected_wrong_year_or_month": True, "search_return_missing_not_proof_source_unavailable": True})
save("八固定定位全部选择与未知_不以错误原期填充_E113.json", {"at": now(), "actual_queries": 8, "selections": selections, "selected_new_first_GETs": 2, "unmatched_original_periods": [item["economic_period"] for item in selections if item["selected_url"] is None], "extra_queries": 0, "alternate_carriers": 0})
def fetch(period, url):
    claim = save(period + "_唯一新首次GET认领_E113.json", {"claimed_at": now(), "source_url": url, "attempt": 1, "retries": 0, "TLS_verify": True, "authenticated_request": False})
    record = {"economic_period": period, "source_url": url, "claim": claim, "started_at": now(), "attempt": 1, "retries": 0, "TLS_verify": True, "authenticated_request": False}
    try:
        response = requests.get(url, verify=True, timeout=(12, 30), allow_redirects=False)
        target = out / (period + "_唯一新首次取得原响应_E113.html")
        if target.exists():
            raise RuntimeError("原响应已有")
        target.write_bytes(response.content)
        record.update({"status_code": response.status_code, "response_url": response.url, "location": response.headers.get("Location"), "bytes": len(response.content), "raw_path": str(target.relative_to(root)).replace("\\", "/"), "raw_sha256": sha(target), "status": "FIRST_GET_HTTP_200_RAW_SAVED" if response.status_code == 200 else "UNKNOWN_FIRST_GET_NON_200_NO_RETRY"})
    except Exception as exc:
        record.update({"status": "UNKNOWN_FIRST_GET_TRANSPORT_FAILURE_NO_RETRY", "error_type": type(exc).__name__, "error": str(exc)})
    record["ended_at"] = now()
    save(period + "_唯一新首次GET回执_E113.json", record)
    return record
results = []
with ThreadPoolExecutor(max_workers=2) as pool:
    futures = [pool.submit(fetch, period, url) for period, url in selected_urls.items()]
    for future in as_completed(futures):
        record = future.result()
        results.append(record)
        print(json.dumps({key: record.get(key) for key in ["economic_period", "status", "status_code", "bytes"]}, ensure_ascii=False), flush=True)
save("有限新定位与首次取得完成_E113.json", {"at": now(), "actual_fixed_queries": 8, "existing_full_raw_reuses": 5, "actual_new_distinct_first_GETs": 2, "results": sorted(results, key=lambda item:item["economic_period"]), "no_query_match_original_periods": [item["economic_period"] for item in selections if not item["selected_url"]], "new_GET_retries": 0, "extra_queries": 0, "alternate_carrier_GETs": 0, "source_locator_route_completed": True, "missing_not_proven_unavailable": True})
